node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { resolveName } from './src/registry.mjs';
import { buildOrder } from './src/order.mjs';

const nodes = {
  app: { dependencies: ['coreAlias', 'core'] },
  core: {},
  unused: { dependencies: ['missing'] },
};
const aliases = { appAlias: 'app', coreAlias: 'core', core: 'coreAlias' };
assert.equal(resolveName('appAlias', nodes, aliases), 'app');
assert.deepEqual(buildOrder({ nodes, aliases }, ['appAlias', 'coreAlias', 'core']), ['core', 'app']);
assert.throws(() => resolveName('a', nodes, { a: 'b', b: 'a' }), /Alias cycle/);
assert.throws(() => resolveName('missing', nodes, {}), /Unknown node/);
assert.throws(() => buildOrder({
  nodes: { a: { dependencies: ['aliasB'] }, b: { dependencies: ['aliasA'] } },
  aliases: { aliasA: 'a', aliasB: 'b' },
}, ['a']), /Dependency cycle/);
assert.throws(() => resolveName('toString', {}, {}), /Unknown node/);
console.log('alias contract checks passed');
EOF

