patches.before:
export function resolveName(name, nodes, aliases) {
  const target = aliases[name] ?? name;
  if (!(target in nodes)) throw new Error('Unknown node: ' + target);
  return target;
}

patches.after:
export function resolveName(name, nodes, aliases = {}) {
  const seen = new Set();

  while (Object.hasOwn(aliases, name)) {
    if (seen.has(name)) throw new Error('Alias cycle: ' + name);
    seen.add(name);
    name = aliases[name];
  }

  if (!Object.hasOwn(nodes, name)) throw new Error('Unknown node: ' + name);
  return name;
}
